using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;

// Pose-controlled runtime acceptance; PVP waits actual host time. Not manual driving/LAN.
public sealed class AccidentWorkshopProbe : MonoBehaviour {
 [Serializable] sealed class Result {public bool success;public string mode,scope,error;public List<string> assertions=new List<string>();}
 DriveSession s;PvpSimulationMatch match;Result result=new Result();string output;bool done,pvp;float deadline;int serial;
 static bool Has(string flag){return Array.IndexOf(Environment.GetCommandLineArgs(),flag)>=0;}
 static string Arg(string flag,string fallback){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,flag);return i>=0&&i+1<a.Length?a[i+1]:fallback;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){if(Has("-accidentWorkshopCheck")||Has("-accidentWorkshopReloadCheck")||Has("-pvpAccidentWorkshopCheck"))new GameObject("Accident workshop acceptance").AddComponent<AccidentWorkshopProbe>();}
 void Check(bool value,string why){result.assertions.Add((value?"PASS ":"FAIL ")+why);Debug.Log("ACCIDENT_WORKSHOP "+result.assertions.Last());if(!value)throw new Exception(why);}
 void Finish(Exception error=null){if(done)return;done=true;result.success=error==null;result.error=error==null?"":error.ToString();Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(result,true));Debug.Log("ACCIDENT_WORKSHOP_PLAYER_"+(result.success?"OK":"FAIL")+" assertions="+result.assertions.Count+" "+result.error);Application.Quit(result.success?0:1);}
 void Update(){if(!done&&deadline>0&&Time.realtimeSinceStartup>deadline)Finish(new TimeoutException("runtime acceptance timeout"));}
 IEnumerator Start(){Application.runInBackground=true;output=Path.GetFullPath(Arg("-accidentWorkshopOutput","artifacts/accident-workshop-player"));deadline=Time.realtimeSinceStartup+180;var run=Run();while(!done){object item;try{if(!run.MoveNext()){Finish();yield break;}item=run.Current;}catch(Exception e){Finish(e);yield break;}yield return item;}}
 void Pose(DriveSession d,Vector3 position,Quaternion rotation,float speed=0){d.taxi.body.constraints=speed==0?RigidbodyConstraints.FreezeAll:RigidbodyConstraints.FreezeRotation;d.taxi.body.position=position;d.taxi.body.rotation=rotation;d.taxi.transform.SetPositionAndRotation(position,rotation);d.taxi.body.velocity=rotation*Vector3.forward*speed;d.taxi.ReplicaVelocity=d.taxi.body.velocity;Physics.SyncTransforms();}
 void Stop(DriveSession d,int index=0){var point=d.jobs.stops[index];Pose(d,point.Kerb+Vector3.up*.65f,Quaternion.LookRotation(point.Direction));d.requests.AdvanceSafeStop(2.1f);}
 void Freeze(DriveSession d){d.jobs.enabled=false;d.requests.enabled=false;d.law.enabled=false;d.manners.enabled=false;d.assisted.SetActive(false);d.assisted.enabled=false;d.taxi.enabled=false;d.taxi.body.useGravity=false;d.taxi.body.constraints=RigidbodyConstraints.FreezeAll;d.damage.enabled=false;var brain=d.GetComponent<PvpSimulationBot>();if(brain)brain.enabled=false;var service=d.GetComponent<PvpSimulationBotServices>();if(service)service.enabled=false;}
 void Fresh(){Time.timeScale=1;s.paused=false;s.business.preparing=false;s.accident.Restore(new AccidentState());s.accident.Suppress(0);s.jobs.ClearForDay();s.business.passengers.Clear();s.services.open=false;var panel=s.GetComponent<RideCompletionPanel>();if(panel)panel.Close();if(!pvp){s.business.settings=PrototypeSettings.ForThreeDays();s.business.ledger=new EconomyLedger(s.business.settings);}s.law.ids=new PrototypeIds("accident-probe-"+(serial++));s.business.ledger.Driver.satiety=80;s.business.ledger.Driver.fatigue=0;s.business.ledger.Driver.drowsiness.Recover();Stop(s);}
 void Begin(string target){Check(s.accident.ReportScenarioContact(AccidentKind.Person,target,0),"new contact creates an event");Stop(s);s.accident.Tick(.1f);Check(s.accident.Locked,"vehicle remains locked after stopping");}
 void Board(bool sleeping=false){s.jobs.ForcedPassengerType=sleeping?(PassengerType?)PassengerType.Sleeping:null;s.jobs.ForcedRideCase=sleeping?DrunkRideCase.Random:DrunkRideCase.Normal;var j=s.jobs;j.offers[0]=new JobOffer{pickup=0,drop=3,fare=5000,seconds=1200,requiredScore=60,distance=j.nav.Distance(j.stops[0],j.stops[3]),candidateSeed="accident-board-"+serial};Stop(s);Check(j.Accept(0)&&j.Interact(),"native trip boards before accident");}
 void SingleContracts(){
  Fresh();var e=s.business.ledger;int cash=e.Account.Cash;Begin("ambient:fixture");int durability=s.damage.Damage.Durability;float fuel=e.Account.Fuel;int clean=e.Care.Cleanliness;double elapsed=e.Elapsed,fatigue=e.Driver.fatigue,satiety=e.Driver.satiety;string id=s.accident.State.eventId;
  Check(e.Account.Cash==cash-3000&&e.Account.Expense(e.Day,"accident")==3000,"one 3000 expense when accident starts");s.accident.ReportContact("ambient:second");s.accident.Tick(20);Check(s.accident.State.eventId==id&&e.Account.Expense(e.Day,"accident")==3000,"locked duplicate cannot create second charge");
  Check(e.Elapsed==elapsed&&e.Driver.fatigue==fatigue,"single confirmation wait has no elapsed condition or immediate stress");Check(s.accident.Confirm(),"single confirmation completes treatment");Check(Math.Abs(e.Elapsed-elapsed-45)<.001&&Math.Abs(e.Driver.fatigue-fatigue-3)<.001&&Math.Abs(e.Driver.satiety-satiety+3.75)<.001,"single45 seconds fatigue3 satiety3.75");Check(e.Account.Fuel==fuel&&e.Care.Cleanliness==clean&&s.damage.Damage.Durability==durability,"treatment preserves fuel cleanliness durability");Check(!s.accident.Confirm()&&e.Elapsed==elapsed+45&&e.Account.Expense(e.Day,"accident")==3000,"repeat confirmation never repeats charge or time");
  Fresh();e=s.business.ledger;for(int i=0;i<4;i++)e.Account.Tow("fixture-exhaust-"+i,1);int debt=e.Account.Debt;Check(e.Account.Cash==0,"zero cash fixture");Begin("ambient:debt");Check(e.Account.Debt==debt+3000&&s.accident.Confirm(),"zero cash uses debt and permits recovery");
  Fresh();Board();Begin("ambient:transport");Check(!s.jobs.Active&&s.business.passengers.Count==1&&s.business.passengers[0].paid==0,"on-trip accident records one zero fare cancellation");s.accident.Tick(1);Check(s.business.passengers.Count==1,"resolution cannot duplicate cancellation");s.accident.Confirm();
  Fresh();Board(true);s.jobs.Behavior.Sleeping=true;Stop(s,3);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked,"arrival locks fare before accident");int fare=s.jobs.RequestReward.Total;Begin("ambient:arrival");Check(!s.jobs.Active&&s.business.passengers.Count==1&&s.business.passengers[0].paid==fare,"arrival fare survives accident");s.accident.Confirm();
 }
 void ContactDiagnostic(AmbientPedestrian actor){var box=s.taxi.GetComponent<BoxCollider>();var chest=actor.transform.position+Vector3.up*.85f;var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;bool ready=(bool)typeof(AccidentController).GetProperty("Ready",flags).GetValue(s.accident,null);float grace=(float)typeof(AccidentController).GetField("suppressedUntil",flags).GetValue(s.accident);Debug.Log("ACCIDENT_CONTACT_DIAGNOSTIC actor="+actor.route.id+" visible="+actor.VisualActive+" actorEnabled="+actor.enabled+" gap="+Vector3.Distance(chest,box.ClosestPoint(chest))+" velocity="+s.taxi.ObservedVelocity+" bodyVelocity="+s.taxi.body.velocity+" kinematic="+s.taxi.body.isKinematic+" constraints="+s.taxi.body.constraints+" phase="+s.accident.State.phase+" latched="+s.accident.State.contactLatched+" ready="+ready+" paused="+s.paused+" timeScale="+Time.timeScale+" time="+Time.time+" grace="+grace+" chest="+chest+" bounds="+box.bounds);}
 void RecoveryRegression(){Fresh();Check(s.accident.ReportScenarioContact(AccidentKind.Person,"ambient:recovery-fixture",0),"recovery regression starts event");s.accident.State.recoveryRequired=true;s.accident.State.stopSeconds=5;Stop(s);s.accident.Tick(.1f);Check(!s.accident.State.recoveryRequired,"natural safe stop clears pending recovery requirement");Check(s.accident.Confirm()&&!s.accident.Locked,"recovered event unlocks after confirmation");}
 void ContactDetection(){
  Fresh();Check(s.ambientPedestrians&&s.ambientPedestrians.actors.Count>0,"authored ambient population exists");var actor=s.ambientPedestrians.actors.First(a=>a.gameObject.activeInHierarchy&&a.VisualActive&&!a.state.deferredReveal);actor.enabled=false;var original=actor.transform.position;
  actor.transform.position=s.taxi.transform.position+Vector3.down*.65f;Physics.SyncTransforms();s.accident.Suppress(0);s.accident.ScanContacts();Check(!s.accident.Locked,"stationary contact excluded");Pose(s,s.taxi.transform.position,s.taxi.transform.rotation,1);Check(Math.Abs(s.taxi.ObservedVelocity.magnitude-1)<.001,"low speed fixture actually moves at1m/s");s.accident.ScanContacts();Check(!s.accident.Locked,"one metre per second contact excluded");Pose(s,s.taxi.transform.position,s.taxi.transform.rotation,-2);Check(Math.Abs(s.taxi.Speed+2)<.001,"reverse fixture actually moves at minus2m/s");ContactDiagnostic(actor);s.accident.ScanContacts();Debug.Log("ACCIDENT_CONTACT_AFTER phase="+s.accident.State.phase+" latched="+s.accident.State.contactLatched);Check(s.accident.Locked,"reverse speed detects actual ambient actor");actor.transform.position=original;Stop(s);s.accident.Tick(.1f);s.accident.Confirm();
  Fresh();s.jobs.RefreshWaitingPassengers();int index=Array.FindIndex(s.jobs.people,g=>g&&g.activeInHierarchy);Check(index>=0,"visible waiting passenger exists");var person=s.jobs.people[index];var prior=person.transform.position;person.transform.position=s.taxi.transform.position+Vector3.down*.65f;Physics.SyncTransforms();s.accident.Suppress(0);Pose(s,s.taxi.transform.position,s.taxi.transform.rotation,2);Check(Math.Abs(s.taxi.Speed-2)<.001,"waiting contact fixture actually moves at2m/s");s.accident.ScanContacts();Check(s.accident.Locked&&s.accident.State.targetId.StartsWith("waiting:"),"actual waiting passenger uses common detector");person.transform.position=prior;Stop(s);s.accident.Tick(.1f);s.accident.Confirm();
 }
 void WorkshopLayoutChecks(){Check(s.services.Workshops.Count==2,"two validated workshops in loaded map");s.damage.BuildBays();Check(s.damage.Bays.Count(b=>!b.legacy)==4,"four dedicated workshop tow bays in loaded map");foreach(var site in s.services.Workshops){WorkshopLayout.Validate(s.world.map,site);Check(site.entry.Length>2&&site.departure.Length>2,"validated entry and exit geometry "+site.id);}}
 void DamageTo(DriveSession driver,bool disabled){driver.damage.Damage.Advance(2,false);driver.damage.ApplyImpact(disabled?15:10);if(disabled){driver.damage.Damage.Advance(2,false);driver.damage.ApplyImpact(15);}Check(driver.damage.Damage.Durability==(disabled?0:70),"damage fixture D"+(disabled?0:70));}
 void WorkshopPose(DriveSession driver){var site=driver.services.Workshops[0];Pose(driver,site.repair+Vector3.up*.65f,Quaternion.LookRotation(site.direction));}
 void SingleWorkshops(){Fresh();WorkshopLayoutChecks();DamageTo(s,false);Check(!s.damage.Repair(),"roadside remote repair rejected");WorkshopPose(s);var e=s.business.ledger;int cash=e.Account.Cash;double elapsed=e.Elapsed;float fuel=e.Account.Fuel;int clean=e.Care.Cleanliness;Check(s.damage.Repair(),"normal workshop repair accepted at native bay");Check(s.damage.Damage.Durability==100&&e.Account.Cash==cash-6000&&Math.Abs(e.Elapsed-elapsed-25)<.001,"D70 repair costs6000 and25seconds");Check(e.Account.Fuel==fuel&&e.Care.Cleanliness==clean,"workshop repair preserves fuel and cleanliness");Check(!s.damage.Repair(),"healthy taxi cannot buy another repair");}
 IEnumerator PvpWorkshops(){
  WorkshopLayoutChecks();s.accident.Restore(new AccidentState());s.accident.Suppress(0);s.jobs.ClearForDay();DamageTo(s,false);WorkshopPose(s);var e=s.business.ledger;int cash=e.Account.Cash;float started=match.Elapsed;Check(s.damage.Repair()&&s.damage.PendingServiceRemaining>0,"PVP repair starts pending service");Check(e.Account.Cash==cash&&s.damage.Damage.Durability==70,"PVP repair no early charge or durability gain");
  while(match.Elapsed-started<3)yield return null;Check(e.Account.Cash==cash&&s.damage.Damage.Durability==70,"partial repair still has no reward or fee");s.damage.CancelPendingService();Check(e.Account.Cash==cash&&s.damage.PendingServiceRemaining==0&&s.damage.Damage.Durability==70,"cancelled PVP repair is free and gives no repair");started=match.Elapsed;Check(s.damage.Repair(),"PVP repair can restart after cancellation");while(s.damage.PendingServiceRemaining>0)yield return null;Check(match.Elapsed-started>=24.8&&match.Elapsed-started<27&&s.damage.Damage.Durability==100&&e.Account.Cash==cash-6000,"PVP repair completes after actual25 seconds with one6000 payment");
  int[] expenses=new int[match.Drivers.Count];int index=0;foreach(var driver in match.Drivers){driver.accident.Restore(new AccidentState());driver.accident.Suppress(0);driver.jobs.ClearForDay();Stop(driver,index++);DamageTo(driver,true);driver.damage.BuildBays();expenses[index-1]=driver.business.ledger.Account.Expense(1,"tow");Check(driver.damage.Tow(),"four drivers can reserve distinct tow slots driver="+driver.SimulationDriver);Check(driver.business.ledger.Account.Expense(1,"tow")==expenses[index-1],"tow no early charge driver="+driver.SimulationDriver);}
  started=match.Elapsed;while(match.Drivers.Any(d=>d.damage.PendingServiceRemaining>0))yield return null;Check(match.Elapsed-started>=29.8&&match.Elapsed-started<33,"four simultaneous tow services finish after actual30 seconds");var ids=new HashSet<string>();index=0;foreach(var driver in match.Drivers){Check(driver.damage.AtRepairBay&&ids.Add(driver.damage.Damage.RepairBayId),"tow placement uses unique paid bay driver="+driver.SimulationDriver);Check(driver.business.ledger.Account.Expense(1,"tow")==expenses[index++]+3000&&driver.damage.Disabled,"tow charges3000 once without free repair driver="+driver.SimulationDriver);Check(!driver.damage.Tow(),"paid bay cannot be towed again driver="+driver.SimulationDriver);}
  var repairedBot=match.Bot;repairedBot.damage.NotifyWorkshopRepairCompleted();Check(repairedBot.GetComponent<PvpSimulationBotServices>().Active,"paid-bay bot completion activates root egress controller");
  // Start a paid-bay repair, then interrupt with a new authoritative accident.
  s.accident.Restore(new AccidentState());s.accident.Suppress(0);int interruptedCash=s.business.ledger.Account.Cash;Check(s.damage.Repair()&&s.damage.PendingServiceRemaining>0,"paid-bay repair pending before contact interruption");Check(s.accident.ReportScenarioContact(AccidentKind.Person,"ambient:interrupt-workshop",0),"contact interrupts a pending workshop transaction");Check(s.damage.PendingServiceRemaining==0&&s.business.ledger.Account.Cash==interruptedCash&&s.damage.Disabled,"new accident cancels pending repair without charge or recovery");
  FinishChecks();
  yield return Capture("pvp-four-tow-bays");
 }
 void FinishChecks(){
  Check(s.accident.State.phase==AccidentPhase.Stopping&&!s.accident.State.chargeApplied,"match-end fixture has an uncharged stopping event");int endExpense=s.business.ledger.Account.Expense(1,"accident"),endScore=match.Score(s.SimulationDriver);float endClock=match.Elapsed;double endLedgerTime=s.business.ledger.Elapsed;match.Finish();
  Check(s.business.ledger.Account.Expense(1,"accident")==endExpense+3000&&s.accident.State.chargeApplied,"match end charges last-second stopping accident exactly once");Check(match.Elapsed==endClock&&s.business.ledger.Elapsed==endLedgerTime,"match end settlement adds no clock or treatment time");Check(match.Score(s.SimulationDriver)==endScore-3000,"final score reflects last-second accident expense");match.Finish();Check(s.business.ledger.Account.Expense(1,"accident")==endExpense+3000&&match.Score(s.SimulationDriver)==endScore-3000&&match.Elapsed==endClock,"repeated match finish cannot duplicate expense score or time");
 }
 IEnumerator Capture(string name){if(!Has("-accidentWorkshopCapture")||SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)yield break;while(!UnityEngine.Rendering.SplashScreen.isFinished)yield return null;yield return null;yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();try{Directory.CreateDirectory(output);File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());}finally{Destroy(image);}}
 IEnumerator Run(){
  pvp=Has("-pvpAccidentWorkshopCheck");result.mode=pvp?"pvp":"single";result.scope="Pose-controlled contact and transaction fixtures; actual PVP45 second host timer; not manual driving or LAN";
  if(pvp){if(!FindObjectOfType<Pvp.PvpBootstrap>()){var unified=FindObjectOfType<UnifiedModeBootstrap>();if(unified)unified.StartPvp();}Pvp.PvpBootstrap boot;while(!(boot=FindObjectOfType<Pvp.PvpBootstrap>()))yield return null;boot.StartSimulation(true,600);while(!(match=FindObjectOfType<PvpSimulationMatch>())||!match.Human||!match.Human.StartupReady)yield return null;s=match.Human;}
  else {while(!(s=FindObjectOfType<DriveSession>())||!s.StartupReady)yield return null;Check(s.business.SavePath.Replace('\\','/').Contains("/artifacts/"),"isolated artifact campaign save");}
  // StartupReady precedes the deferred live checkpoint restore coroutine.
  yield return null;while(s.business.IsRestoring)yield return null;
  if(!pvp){Check(!s.business.ResumeBlocked,"campaign restore completed without blocking");if(Has("-accidentWorkshopReloadCheck"))Check(s.accident&&s.accident.Locked&&s.accident.State.chargeApplied,"restored paid pending state before any fixture mutation");}
  Check(s.accident!=null,"production accident controller attached");Freeze(s);s.business.preparing=false;s.paused=false;Time.timeScale=1;
  if(!pvp){s.business.enabled=false;if(Has("-accidentWorkshopReloadCheck")){var e=s.business.ledger;Check(s.accident.Locked&&s.accident.State.chargeApplied,"new process restores paid pending event");Check(e.Account.Expense(e.Day,"accident")==3000,"reload retains one expense");double before=e.Elapsed;Check(s.accident.Confirm()&&e.Elapsed==before+45,"reload completes remaining transaction once");Check(!s.accident.Confirm()&&e.Elapsed==before+45,"reload repeat is idempotent");yield break;}
   SingleContracts();RecoveryRegression();ContactDetection();SingleWorkshops();Fresh();Begin("ambient:checkpoint");s.business.SaveCheckpoint();Check(!s.business.SaveFailed,"pending checkpoint writes");yield return Capture("single-pending");yield break;
  }
  Fresh();foreach(var bot in match.Bots)Freeze(bot);if(Has("-accidentEndOnly")){Check(s.accident.ReportScenarioContact(AccidentKind.Person,"ambient:end-only",0),"end-only fresh contact starts event");FinishChecks();yield break;}var other=match.Bot;other.jobs.ClearForDay();Stop(other);other.accident.Restore(new AccidentState());other.accident.Suppress(0);int humanExpense=s.business.ledger.Account.Expense(1,"accident"),botExpense=other.business.ledger.Account.Expense(1,"accident");float clock=match.Elapsed;double otherElapsed=other.business.ledger.Elapsed;
  Begin("ambient:pvp-human");Check(other.accident.ReportScenarioContact(AccidentKind.Person,"ambient:pvp-bot",0),"bot creates same accident event");other.accident.Tick(.1f);Check(other.accident.Locked,"bot obeys same lock");yield return Capture("pvp-pending");while(match.Elapsed-clock<10)yield return null;Check(s.accident.Locked&&other.accident.Locked,"both locked after actual10 host seconds");Check(match.Elapsed-clock<11&&other.business.ledger.Elapsed>otherElapsed,"shared clock advances without45 second jump");while(s.accident.Locked||other.accident.Locked)yield return null;
  Check(match.Elapsed-clock>=44.8&&match.Elapsed-clock<47,"human and bot unlock after actual45 host seconds");Check(s.business.ledger.Account.Expense(1,"accident")==humanExpense+3000&&other.business.ledger.Account.Expense(1,"accident")==botExpense+3000,"human and bot each pay exactly3000 once");Check(s.business.SavePath==""&&other.business.SavePath=="","PVP never writes campaign save");yield return Capture("pvp-completed");var workshop=PvpWorkshops();while(workshop.MoveNext())yield return workshop.Current;
 }
}
